<script setup lang="ts">
import type { DocumentRecord, Page } from '~/utils/types'
const { actor, admin, unitAdmin, courier } = useSession()
const records = ref<DocumentRecord[]>([]); const error = ref<unknown>(); const loading = ref(true)
onMounted(async () => { try { if (actor.value?.memberships.some(m => m.is_active)) records.value = (await useApi().get<Page<DocumentRecord>>('/documents?scope=origin&limit=5')).items } catch (e) { error.value = e } finally { loading.value = false } })
</script>
<template><div class="page-head"><div><h1>ภาพรวมพื้นที่ทำงาน</h1><p>สวัสดี {{ actor?.display_name }} เลือกงานตามสิทธิ์ของบัญชีคุณ</p></div><NuxtLink v-if="actor?.memberships.some(m => m.is_active)" class="button primary" to="/documents/new">ลงทะเบียนหนังสือ</NuxtLink></div><Feedback :error="error" /><div class="split"><section class="panel"><h2>หนังสือของหน่วยงานล่าสุด</h2><UProgress v-if="loading" aria-label="กำลังโหลดหนังสือ" /><div v-else-if="!records.length" class="empty"><h3>ยังไม่มีหนังสือในทะเบียนที่คุณเข้าถึง</h3><p>หนังสือจะแสดงตามหน่วยงานต้นทางของคุณ</p></div><div v-for="doc in records" :key="doc.id" class="timeline"><div class="actions"><NuxtLink class="text-link" :to="`/documents/${doc.id}`">{{ doc.title || doc.document_number }}</NuxtLink><StatusTag :value="doc.business_state" /><StatusTag :value="doc.process_sync_status" /></div></div><NuxtLink v-if="records.length" to="/documents" class="button actions">ดูทะเบียนหนังสือ</NuxtLink></section><section class="panel"><h2>งานที่คุณจัดการได้</h2><div class="stack"><NuxtLink v-if="actor?.station_ids.length" class="button" to="/worklist">เปิดงานประจำ Station</NuxtLink><NuxtLink v-if="courier" class="button" to="/reservations">ตรวจการจองของฉัน</NuxtLink><NuxtLink v-if="admin" class="button" to="/admin/units">เพิ่มและจัดการหน่วยงาน</NuxtLink><NuxtLink v-if="admin || unitAdmin" class="button" to="/admin/users">จัดการผู้ใช้หน่วยงาน</NuxtLink><NuxtLink v-if="admin" class="button" to="/admin/notifications">ตรวจอีเมลแจ้งเตือน</NuxtLink><NuxtLink class="button" to="/profile">ตรวจข้อมูลบัญชีและสิทธิ์</NuxtLink></div></section></div></template>
